view_spec.config:
{
  "view": {
    "type": "view.list",
    "items": [
      {
        "type": "view.text",
        "content": "Проверьте весь кадр: все ли бабочки выделены, нет ли лишних рамок и ошибок границ. Пустую разметку тоже проверьте."
      },
      {
        "type": "helper.if",
        "condition": {
          "type": "condition.equals",
          "data": {
            "type": "data.input",
            "path": "source_status"
          },
          "to": "HAS_BUTTERFLY"
        },
        "then": {
          "type": "view.text",
          "content": "Ответ разметчика: бабочки есть."
        },
        "else": {
          "type": "helper.if",
          "condition": {
            "type": "condition.equals",
            "data": {
              "type": "data.input",
              "path": "source_status"
            },
            "to": "NO_BUTTERFLY"
          },
          "then": {
            "type": "view.text",
            "content": "Ответ разметчика: бабочек нет."
          },
          "else": {
            "type": "helper.if",
            "condition": {
              "type": "condition.equals",
              "data": {
                "type": "data.input",
                "path": "source_status"
              },
              "to": "UNSURE"
            },
            "then": {
              "type": "view.text",
              "content": "Ответ разметчика: не уверен, нужен разбор."
            },
            "else": {
              "type": "view.text",
              "content": "Ответ разметчика: изображение не загрузилось."
            }
          }
        }
      },
      {
        "type": "field.image-annotation",
        "image": {
          "type": "data.input",
          "path": "image"
        },
        "data": {
          "type": "data.internal",
          "path": "review_regions",
          "default": {
            "type": "data.input",
            "path": "result"
          }
        },
        "disabled": true,
        "shapes": {
          "rectangle": true
        },
        "fullHeight": true
      },
      {
        "type": "field.radio-group",
        "data": {
          "type": "data.output",
          "path": "verdict"
        },
        "options": [
          {
            "value": "OK",
            "label": "Всё верно"
          },
          {
            "value": "BAD",
            "label": "Есть ошибка"
          },
          {
            "value": "UNSURE",
            "label": "Не уверен"
          },
          {
            "value": "IMAGE_ERROR",
            "label": "Изображение не загрузилось"
          }
        ],
        "validation": {
          "type": "condition.required",
          "hint": "Выберите один ответ."
        }
      }
    ]
  },
  "plugins": [
    {
      "type": "plugin.toloka",
      "layout": {
        "kind": "scroll",
        "taskWidth": 1000
      }
    }
  ]
}
